window.__GUIDE_CHUNKS__.push([{"id": "07-008", "chapter_num": 7, "chapter_title": "When You're Broke", "chapter_file": "07-when-youre-broke.md", "number": 8, "title": "Job-search coaching: 2.67 times the odds of finding work", "money": "0", "time": "mid", "willpower": "yes", "benefit": "mid", "dimension": "money", "evidence": "A", "grade": "A", "disputed": false, "cost": "No money. Skip paid courses; the price is 1 to 2 hours a day for several weeks, plus the discipline to keep going when nobody is watching.", "plain": "People who took structured job-search coaching found work at 2.67 times the odds of people who did not, across 47 studies. What worked: learning concrete skills, presenting yourself clearly, setting targets, and asking people for help.", "benefit_text": "Meta-analysis of 47 job-search intervention studies (2014): participants had 2.67 times the odds of finding employment (OR 2.67) versus controls. Effective components: teaching search skills, improving self-presentation, building self-efficacy, encouraging proactivity, goal setting, and enlisting social support.", "sources": "https://doi.org/10.1037/a0035923", "notes": "Liu, Huang, Wang (2014), Psychological Bulletin 140(4): 1009–1041. Most studies ran in Western countries as group programs; the mechanism travels, the setting differs. Benefit graded mid by judgment: finding work even a few months sooner at low wages is worth well over $5,000.", "urls": ["https://doi.org/10.1037/a0035923"]}, {"id": "07-009", "chapter_num": 7, "chapter_title": "When You're Broke", "chapter_file": "07-when-youre-broke.md", "number": 9, "title": "Unpaid wages: claim through provincial employment standards", "money": "0", "time": "mid", "willpower": "some", "benefit": "mid", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "No money to file. The work is gathering pay stubs, schedules and transfer records; expect weeks to months for a decision.", "plain": "If your employer will not pay what you are owed, you do not need a lawyer to start. In Ontario, file a claim with the Ministry of Labour; in Quebec, complain to the CNESST. Keep every pay stub, schedule, and message about pay.", "benefit_text": "Ontario: unpaid-wage claims go to the Ministry of Labour under the ESA (claim within 2 years); Quebec: complaints go to the CNESST. Filing is free in both provinces.", "sources": "https://www.ontario.ca/laws/statute/00e41/v24 ; https://www.cnesst.gouv.qc.ca/en/working-conditions/wage-and-pay/wages/overtime", "notes": "There is no labour-arbitration step in Canada: Ontario goes through the Ministry, Quebec through the CNESST. Quebec complaint deadlines UNVERIFIED at write time — file promptly; see docs/verification/07-when-youre-broke.md #3. Benefit graded mid by judgment: several weeks of recovered wages at full time typically exceed $5,000.", "urls": ["https://www.cnesst.gouv.qc.ca/en/working-conditions/wage-and-pay/wages/overtime", "https://www.ontario.ca/laws/statute/00e41/v24"]}, {"id": "07-010", "chapter_num": 7, "chapter_title": "When You're Broke", "chapter_file": "07-when-youre-broke.md", "number": 10, "title": "Never pay to get hired; report scams to the CAFC", "money": "0", "time": "low", "willpower": "some", "benefit": "low", "dimension": "money", "evidence": "C", "grade": "C", "disputed": false, "cost": "No money. The hard part is saying no on the spot, when you need the job most.", "plain": "No real employer charges you to start work. Walk away from placement fees, deposits, training loans tied to a job offer, and recruiting that pays you for bringing in friends. Report every scam to the Canadian Anti-Fraud Centre, even if you lost nothing.", "benefit_text": "Canadian Anti-Fraud Centre (2026): report all scams and fraud to the CAFC even if you were not a victim; the CAFC collects fraud and identity-theft intelligence to assist law enforcement. The CAFC does not investigate cases or recover money — also report to local police and check both credit bureaus.", "sources": "https://www.canada.ca/en/revenue-agency/campaigns/fraud-scams.html", "notes": "CAFC: 1-888-495-8501 (per substitution research; a write-time primary URL showing the number was not captured — see docs/verification/07-when-youre-broke.md #4). The CAFC collects intelligence; it does not investigate or recover money. Benefit graded low by judgment: the item prevents losses rather than creating income.", "urls": ["https://www.canada.ca/en/revenue-agency/campaigns/fraud-scams.html"]}, {"id": "08-001", "chapter_num": 8, "chapter_title": "Don't get entangled (trouble with others)", "chapter_file": "08-dont-get-entangled.md", "number": 1, "title": "Never lend your bank account, card, or ID to move someone else's money", "money": "0", "time": "low", "willpower": "some", "benefit": "high", "dimension": "freedom", "evidence": "B (statute rules stated as fact)", "grade": "B", "disputed": false, "cost": "$0 (2026). A minute to refuse; some willpower when a friend, a romantic contact, or an online \"job\" offers easy money for \"just receiving a transfer.\"", "plain": "Moving money for strangers is how ordinary people become money mules. The transfer looks harmless; the prison sentence is not. Saying no costs nothing.", "benefit_text": "Money laundering carries up to 10 years in prison (Criminal Code s.462.31, 2026); trafficking in identity information carries up to 5 years (s.402.2(2), 2026). Courts may infer guilty knowledge from markedly unusual dealings (s.462.31(2.3), 2026).", "sources": "https://laws-lois.justice.gc.ca/eng/acts/c-46/section-462.31.html; s.402.2 (identity theft / trafficking in identity information, up to 5 years) — https://laws-lois.justice.gc.ca/eng/acts/c-46/section-402.2.html", "notes": "Covers the platform-rebate and loan-packaging trap: any scheme that routes money through your account is money laundering under Canadian law, regardless of what the platform calls it.", "urls": ["https://laws-lois.justice.gc.ca/eng/acts/c-46/section-402.2.html", "https://laws-lois.justice.gc.ca/eng/acts/c-46/section-462.31.html;"]}, {"id": "08-002", "chapter_num": 8, "chapter_title": "Don't get entangled (trouble with others)", "chapter_file": "08-dont-get-entangled.md", "number": 2, "title": "Get clear, ongoing consent, and respect the age of consent", "money": "0", "time": "low", "willpower": "some", "benefit": "high", "dimension": "freedom", "evidence": "B (statute rules stated as fact)", "grade": "B", "disputed": false, "cost": "$0 (2026). Ongoing attention; some willpower to stop when the answer is not a clear yes.", "plain": "Silence, freezing, \"not saying no\" — none of these is consent. The age of consent is 16 — dating a 15-year-old as an adult is a criminal offence, not a grey area. When in doubt, stop.", "benefit_text": "Sexual assault carries up to 10 years (s.271, 2026), and 14 years with a 1-year minimum where the complainant is under 16. Consent is no defence where the other person is under 16 (s.150.1, 2026). The only close-in-age exceptions: ages 12–13 with a partner less than 2 years older, and ages 14–15 with a partner less than 5 years older; never where there is trust, authority, or dependency.", "sources": "https://laws-lois.justice.gc.ca/eng/acts/c-46/section-271.html https://laws-lois.justice.gc.ca/eng/acts/c-46/section-150.1.html", "notes": "", "urls": ["https://laws-lois.justice.gc.ca/eng/acts/c-46/section-150.1.html", "https://laws-lois.justice.gc.ca/eng/acts/c-46/section-271.html"]}, {"id": "08-003", "chapter_num": 8, "chapter_title": "Don't get entangled (trouble with others)", "chapter_file": "08-dont-get-entangled.md", "number": 3, "title": "Never drive after drinking or using drugs — arrange the ride before the first drink", "money": "0", "time": "low", "willpower": "yes", "benefit": "high", "dimension": "freedom", "evidence": "B (statute rule stated as fact)", "grade": "B", "disputed": false, "cost": "$0–$40 (2026). A taxi or ride-share home, or a designated driver; real willpower to hand over the keys.", "plain": "Canada has one criminal line and no warning tier. A single decision — the ride home booked before the evening starts — keeps a criminal record off your file.", "benefit_text": "Driving with 80 mg or more of alcohol per 100 mL of blood within 2 hours of driving is a criminal offence (s.320.14, 2026). Canada has no two-tier system separating light drinking from drunk driving: one line, criminal above it.", "sources": "https://laws-lois.justice.gc.ca/eng/acts/c-46/section-320.14.html", "notes": "", "urls": ["https://laws-lois.justice.gc.ca/eng/acts/c-46/section-320.14.html"]}, {"id": "08-004", "chapter_num": 8, "chapter_title": "Don't get entangled (trouble with others)", "chapter_file": "08-dont-get-entangled.md", "number": 4, "title": "If police detain or arrest you: ask for counsel, then stay silent", "money": "0", "time": "low", "willpower": "some", "benefit": "high", "dimension": "freedom", "evidence": "B (constitutional and statute rules stated as fact)", "grade": "B", "disputed": false, "cost": "$0 (2026). Minutes of discomfort; some willpower to keep quiet under pressure.", "plain": "The moment police detain you, say you want a lawyer and then say nothing else. Anything you say becomes evidence. Silence cannot be used against you; talking almost always can.", "benefit_text": "The Charter guarantees the right to retain and instruct counsel without delay (s.10(b), 2026); statements taken after that right is denied can be excluded from trial (s.24(2), 2026). Resisting or obstructing a peace officer carries up to 2 years (s.129(a), 2026); assaulting one up to 5 years (s.270, 2026).", "sources": "https://laws-lois.justice.gc.ca/eng/const/page-12.html https://laws-lois.justice.gc.ca/eng/acts/c-46/section-129.html", "notes": "Graded high (judgment call per §5): invoking counsel and silence is the single action most likely to keep a charge from becoming a conviction.", "urls": ["https://laws-lois.justice.gc.ca/eng/acts/c-46/section-129.html", "https://laws-lois.justice.gc.ca/eng/const/page-12.html"]}, {"id": "08-005", "chapter_num": 8, "chapter_title": "Don't get entangled (trouble with others)", "chapter_file": "08-dont-get-entangled.md", "number": 5, "title": "After any collision: stop, exchange information, and help anyone hurt", "money": "0", "time": "low", "willpower": "some", "benefit": "high", "dimension": "freedom", "evidence": "B (statute rule stated as fact)", "grade": "B", "disputed": false, "cost": "$0 (2026). Minutes at the scene; some willpower when you are shaken and want to leave.", "plain": "Leaving the scene turns a traffic accident into a criminal case. Stop, give your name and address, and help anyone injured — then call your insurer.", "benefit_text": "Failing to stop — to give your name and address and offer assistance — is its own criminal offence (s.320.16, 2026), separate from whatever caused the collision.", "sources": "https://laws-lois.justice.gc.ca/eng/acts/c-46/section-320.16.html", "notes": "", "urls": ["https://laws-lois.justice.gc.ca/eng/acts/c-46/section-320.16.html"]}, {"id": "08-006", "chapter_num": 8, "chapter_title": "Don't get entangled (trouble with others)", "chapter_file": "08-dont-get-entangled.md", "number": 6, "title": "Walk away from fights — force is lawful only to defend, and only reasonable force", "money": "0", "time": "low", "willpower": "yes", "benefit": "high", "dimension": "freedom", "evidence": "B (statute rules stated as fact)", "grade": "B", "disputed": false, "cost": "$0 (2026). Pride swallowed; real willpower to walk away from provocation.", "plain": "Self-defence protects the person who uses reasonable, proportionate force to stop an attack — never the person who escalates, chases, settles a score. The law rewards the one who leaves.", "benefit_text": "Assault carries up to 5 years (s.266, 2026); with a weapon or causing bodily harm up to 10 years (s.267, 2026); aggravated assault up to 14 years (s.268, 2026). Self-defence (s.34, 2026) covers only reasonable force judged against the listed factors.", "sources": "https://laws-lois.justice.gc.ca/eng/acts/c-46/section-266.html https://laws-lois.justice.gc.ca/eng/acts/c-46/section-34.html", "notes": "", "urls": ["https://laws-lois.justice.gc.ca/eng/acts/c-46/section-266.html", "https://laws-lois.justice.gc.ca/eng/acts/c-46/section-34.html"]}, {"id": "08-007", "chapter_num": 8, "chapter_title": "Don't get entangled (trouble with others)", "chapter_file": "08-dont-get-entangled.md", "number": 7, "title": "Never threaten to kill or hurt anyone, and never stalk — get a peace bond if you are the target", "money": "0", "time": "low", "willpower": "some", "benefit": "high", "dimension": "freedom", "evidence": "B (statute rules stated as fact)", "grade": "B", "disputed": false, "cost": "$0 (2026). Some willpower to delete the angry message instead of sending it.", "plain": "Words said in anger count. Threats, repeated following, and monitoring someone's movements are criminal offences — and if someone is doing it to you, a judge can order them to stay away for a full year.", "benefit_text": "Uttering threats of death or bodily harm carries up to 5 years (s.264.1, 2026). Criminal harassment (stalking) carries up to 10 years (s.264, 2026), including monitoring a person's location, movements, or social interactions. A s.810 peace bond can impose conditions for up to 12 months; refusing to enter one can mean up to 12 months in prison (s.810(3)–(3.01), 2026).", "sources": "https://laws-lois.justice.gc.ca/eng/acts/c-46/section-264.1.html https://laws-lois.justice.gc.ca/eng/acts/c-46/section-264.html https://laws-lois.justice.gc.ca/eng/acts/c-46/section-810.html", "notes": "Ontario: a Family Law Act s.46 restraining order is also available in family contexts. Quebec: a civil protection order under the Code of Civil Procedure, art.509 (regular order up to 5 years, provisional up to 10 days), instead of or alongside a peace bond.", "urls": ["https://laws-lois.justice.gc.ca/eng/acts/c-46/section-264.1.html", "https://laws-lois.justice.gc.ca/eng/acts/c-46/section-264.html", "https://laws-lois.justice.gc.ca/eng/acts/c-46/section-810.html"]}, {"id": "08-008", "chapter_num": 8, "chapter_title": "Don't get entangled (trouble with others)", "chapter_file": "08-dont-get-entangled.md", "number": 8, "title": "If someone threatens to publish your intimate images: don't pay, keep the messages, report", "money": "0", "time": "mid", "willpower": "some", "benefit": "high", "dimension": "freedom", "evidence": "B (statute rules stated as fact)", "grade": "B", "disputed": false, "cost": "$0 (2026) — paying is what the scammer wants. Hours to report and preserve evidence; some willpower under shame and fear.", "plain": "The threat itself is the crime. Do not pay, do not argue, do not delete: screenshot everything and take it to police. Payment never ends it — it marks you as someone who pays.", "benefit_text": "Extortion carries up to life imprisonment (s.346(1.1)(b), 2026). Threatening to publish an intimate image carries up to 10 years (s.162.1(1.1), 2026), and the offence covers AI-generated likenesses (s.162.1(2)(b), 2026).", "sources": "https://laws-lois.justice.gc.ca/eng/acts/c-46/section-346.html https://laws-lois.justice.gc.ca/eng/acts/c-46/section-162.1.html", "notes": "", "urls": ["https://laws-lois.justice.gc.ca/eng/acts/c-46/section-162.1.html", "https://laws-lois.justice.gc.ca/eng/acts/c-46/section-346.html"]}, {"id": "08-009", "chapter_num": 8, "chapter_title": "Don't get entangled (trouble with others)", "chapter_file": "08-dont-get-entangled.md", "number": 9, "title": "Hang up on the scam call; verify through an independent channel", "money": "0", "time": "low", "willpower": "some", "benefit": "mid", "dimension": "money", "evidence": "B (official agency guidance stated as fact)", "grade": "B", "disputed": false, "cost": "$0 (2026). About 10 minutes to verify through an independent channel; reporting a real loss takes 1–2 hours with local police and the credit bureaus.", "plain": "The caller who says your account is frozen, your parcel is held, you missed jury duty — is not who they claim to be. Hang up, find the real number yourself, call back. Ten minutes of checking is the whole defence.", "benefit_text": "Avoids per-incident losses in the $5,000–$50,000 range (graded mid per §5 money thresholds; judgment call, see Notes, 2026). Report real losses to the Canadian Anti-Fraud Centre (1-888-495-8501) and to local police; CAFC collects intelligence and does not investigate or recover funds.", "sources": "https://antifraudcentre-centreantifraude.ca/features-vedette/2024/10/identity-fraud-fraude-identite-eng.htm", "notes": "Graded mid (judgment call per §5): a single impersonation-scam loss commonly reaches five figures while the precaution costs minutes. Never \"verify\" by calling back the number the caller gave you.", "urls": ["https://antifraudcentre-centreantifraude.ca/features-vedette/2024/10/identity-fraud-fraude-identite-eng.htm"]}, {"id": "08-010", "chapter_num": 8, "chapter_title": "Don't get entangled (trouble with others)", "chapter_file": "08-dont-get-entangled.md", "number": 10, "title": "Guard your ID and SIN; check both credit bureaus after any suspected identity fraud", "money": "0", "time": "low", "willpower": "no", "benefit": "mid", "dimension": "money", "evidence": "B (statute rules and official guidance stated as fact)", "grade": "B", "disputed": false, "cost": "$0 (2026). Minutes to request your free reports from Equifax and TransUnion; a fraud alert is free.", "plain": "Your SIN plus your name and birth date is a full identity kit. After any breach, any lost wallet, pull both credit reports, place a fraud alert — the paper trail you create now is what unwinds the damage later.", "benefit_text": "Identity theft carries up to 5 years (s.402.2(1), 2026); trafficking in identity information up to 5 years (s.402.2(2), 2026); identity fraud up to 10 years (s.403, 2026). A CAFC report (1-888-495-8501) plus reports to both bureaus documents the fraud for lenders and police.", "sources": "https://laws-lois.justice.gc.ca/eng/acts/c-46/section-402.2.html https://laws-lois.justice.gc.ca/eng/acts/c-46/section-403.html", "notes": "Graded mid (judgment call per §5): cleaning up identity fraud commonly costs a victim thousands of dollars and months of disputes; early detection keeps it small.", "urls": ["https://laws-lois.justice.gc.ca/eng/acts/c-46/section-402.2.html", "https://laws-lois.justice.gc.ca/eng/acts/c-46/section-403.html"]}, {"id": "08-011", "chapter_num": 8, "chapter_title": "Don't get entangled (trouble with others)", "chapter_file": "08-dont-get-entangled.md", "number": 11, "title": "You may record a call you take part in; you may not intercept calls you are not part of", "money": "0", "time": "low", "willpower": "no", "benefit": "low", "dimension": "freedom", "evidence": "B (statute rule stated as fact)", "grade": "B", "disputed": false, "cost": "$0 (2026). A phone's built-in recorder; no extra effort.", "plain": "Canada has one-party consent: recording a conversation you are part of is lawful, and the recording is usable evidence later. Intercepting conversations you are not part of is a criminal offence. Know which side of that line you are on.", "benefit_text": "Intercepting a communication you are neither the originator nor the intended recipient of carries up to 5 years (s.184, 2026); recording a call you take part in needs only your own consent and the recording is admissible in later disputes.", "sources": "https://laws-lois.justice.gc.ca/eng/acts/c-46/section-184.html", "notes": "", "urls": ["https://laws-lois.justice.gc.ca/eng/acts/c-46/section-184.html"]}, {"id": "08-012", "chapter_num": 8, "chapter_title": "Don't get entangled (trouble with others)", "chapter_file": "08-dont-get-entangled.md", "number": 12, "title": "Put every loan and every co-signing promise in writing", "money": "0", "time": "low", "willpower": "no", "benefit": "low", "dimension": "freedom", "evidence": "C (expert consensus; official court limits stated as fact)", "grade": "C", "disputed": false, "cost": "$0 (2026). Minutes to write down amount, date, and repayment terms, signed by both sides.", "plain": "Memory is not evidence. A short written note — who borrowed what, when it is due back — decides loan disputes in small-claims court. A verbal \"I'll pay you back\" decides nothing.", "benefit_text": "A written record (amount, date, repayment terms) is what decides loan disputes; Ontario Small Claims Court hears claims up to $50,000 (from 1 Oct 2025), Quebec's small-claims division up to $15,000 (2026). Without writing, most private loans are unrecoverable in practice.", "sources": "https://www.ontario.ca/page/suing-someone-small-claims-court", "notes": "Co-signing a lease or loan makes you fully liable for the other person's debt — read what you sign, and keep a copy.", "urls": ["https://www.ontario.ca/page/suing-someone-small-claims-court"]}, {"id": "08-013", "chapter_num": 8, "chapter_title": "Don't get entangled (trouble with others)", "chapter_file": "08-dont-get-entangled.md", "number": 13, "title": "After an accident or dispute, photograph everything and save every message", "money": "0", "time": "low", "willpower": "no", "benefit": "low", "dimension": "freedom", "evidence": "C (expert consensus and standard practice)", "grade": "C", "disputed": false, "cost": "$0 (2026). A few minutes at the scene with your phone; keep originals unedited.", "plain": "Cases are won by whoever has the photos. Car damage, injuries, the icy sidewalk, the landlord's text — capture it now, because the scene will not exist tomorrow.", "benefit_text": "Photo and message evidence decides insurance and court disputes; keep originals unedited (2026). Timestamped originals are what adjusters, police, and judges rely on.", "sources": "https://www.ontario.ca/page/consumer-protection-ontario", "notes": "", "urls": ["https://www.ontario.ca/page/consumer-protection-ontario"]}, {"id": "08-014", "chapter_num": 8, "chapter_title": "Don't get entangled (trouble with others)", "chapter_file": "08-dont-get-entangled.md", "number": 14, "title": "Rescue rules are opposite in the two provinces — know which one you are in", "money": "0", "time": "low", "willpower": "some", "benefit": "low", "dimension": "freedom", "evidence": "B (statute rules quoted verbatim)", "grade": "B", "disputed": false, "cost": "$0 (2026). The willpower to stop and help when it would be easier to walk past.", "plain": "Quebec: you must help someone whose life is in danger, personally, by calling for help. Ontario: no one is required to rescue — but a person who gives emergency first aid at the scene is protected from lawsuits for ordinary negligence.", "benefit_text": "Quebec — \"Every person must come to the aid of anyone whose life is in peril, either personally or calling for aid, by giving him the necessary and immediate physical assistance, unless it involves danger to himself or a third person, or he has another valid reason\" (Charter of Human Rights and Freedoms, art.2, 2026). Ontario — a first-aider at the immediate scene \"is not liable for damages that result from the person's alleged negligence in acting or failing to act, unless it is established that the damages were caused by the gross negligence of the person\" (Good Samaritan Act, 2001, s.2(1), 2026).", "sources": "https://www.legisquebec.gouv.qc.ca/fr/document/lc/C-12/20050617?langCont=en https://www.ontario.ca/laws/statute/01g02", "notes": "Two clearly labelled halves per §7.2 (opposite answers). Quebec's duty is a civil obligation, not a criminal offence; graded low (avoids civil exposure).", "urls": ["https://www.legisquebec.gouv.qc.ca/fr/document/lc/C-12/20050617?langCont=en", "https://www.ontario.ca/laws/statute/01g02"]}, {"id": "08-015", "chapter_num": 8, "chapter_title": "Don't get entangled (trouble with others)", "chapter_file": "08-dont-get-entangled.md", "number": 15, "title": "In a mental-health crisis, call 911 and describe the crisis — don't restrain the person yourself", "money": "0", "time": "low", "willpower": "some", "benefit": "mid", "dimension": "freedom", "evidence": "B (statute rule; official emergency guidance)", "grade": "B", "disputed": false, "cost": "$0 (2026). The call; some willpower to stay calm and keep your distance.", "plain": "You cannot help by grabbing, holding, locking someone in. Physically restraining a person in crisis is assault in the eyes of the law, and it usually makes the crisis worse. Call 911, say it is a mental-health crisis, describe exactly what is happening, let trained responders take over.", "benefit_text": "Non-consensual physical restraint is assault — up to 5 years (s.266, 2026). A 911 call describing the crisis brings trained responders and creates a record; police have apprehension powers for persons in crisis that private citizens do not.", "sources": "https://laws-lois.justice.gc.ca/eng/acts/c-46/section-266.html", "notes": "Graded mid (judgment call per §5): a restraint gone wrong leads to detention and assault charges.", "urls": ["https://laws-lois.justice.gc.ca/eng/acts/c-46/section-266.html"]}, {"id": "08-016", "chapter_num": 8, "chapter_title": "Don't get entangled (trouble with others)", "chapter_file": "08-dont-get-entangled.md", "number": 16, "title": "There is no statutory surrender discount — talk to counsel before saying anything", "money": "0", "time": "low", "willpower": "some", "benefit": "mid", "dimension": "freedom", "evidence": "B (constitutional rules; documented institutional difference in research/law-substitution.md)", "grade": "B", "disputed": false, "cost": "$0 (2026). Some willpower to stay silent when confessing feels like the faster way out.", "plain": "Canada has no voluntary-surrender discount: no statute reduces a sentence because you turned yourself in, confessed early. An early guilty plea is only common-law mitigation at sentencing, and everything you tell police becomes evidence against you. The only safe first step is a lawyer.", "benefit_text": "No statute discounts a sentence for surrendering; an early guilty plea is common-law mitigation only, and statements made to police are admissible evidence (Charter s.10(b), s.24(2), 2026). Confessing without counsel gives away the strongest leverage a defendant has.", "sources": "https://laws-lois.justice.gc.ca/eng/const/page-12.html", "notes": "Graded mid (judgment call per §5): unrepresented confessions routinely lead to detention and charges that counsel could have challenged. This is a China-to-Canada trap, not a restatement of item 4's behaviour.", "urls": ["https://laws-lois.justice.gc.ca/eng/const/page-12.html"]}, {"id": "08-017", "chapter_num": 8, "chapter_title": "Don't get entangled (trouble with others)", "chapter_file": "08-dont-get-entangled.md", "number": 17, "title": "Canada has no 检察院 — know who actually decides your case", "money": "0", "time": "low", "willpower": "no", "benefit": "low", "dimension": "time", "evidence": "B (documented institutional difference in research/law-substitution.md)", "grade": "B", "disputed": false, "cost": "$0 (2026). The time to learn a two-sentence institutional map.", "plain": "Police investigate, the Crown (the DPCP in Quebec) decides whether to lay charges, and the victim participates as a witness — not as a party who can appeal a non-prosecution. If you report a crime, your contact is the police file, not a prosecutor's office that takes petitions.", "benefit_text": "Time saved once (2026): victims who understand the Crown model stop chasing a non-existent appeal channel and put their effort into the police report and the victim-services file instead.", "sources": "https://laws-lois.justice.gc.ca/eng/acts/c-46/", "notes": "", "urls": ["https://laws-lois.justice.gc.ca/eng/acts/c-46/"]}, {"id": "08-018", "chapter_num": 8, "chapter_title": "Don't get entangled (trouble with others)", "chapter_file": "08-dont-get-entangled.md", "number": 18, "title": "Canada has no 受案回执 — get the occurrence number and confirm in writing", "money": "0", "time": "low", "willpower": "no", "benefit": "low", "dimension": "freedom", "evidence": "C (standard police practice; expert consensus)", "grade": "C", "disputed": false, "cost": "$0 (2026). Two minutes to ask one question and save the answer.", "plain": "No one will hand you a stamped receipt when you report a crime. What exists is the occurrence, the file number — ask for it, write it down, confirm the report by email, through the service's online portal. Without that number, following up is nearly impossible.", "benefit_text": "The occurrence/file number is the only durable trace of a report (2026); with it you can request updates, add information, and reference the file with insurers and victim services.", "sources": "https://antifraudcentre-centreantifraude.ca", "notes": "", "urls": ["https://antifraudcentre-centreantifraude.ca"]}, {"id": "08-019", "chapter_num": 8, "chapter_title": "Don't get entangled (trouble with others)", "chapter_file": "08-dont-get-entangled.md", "number": 19, "title": "Canada has no 居委会 or 妇联 — go to the body that actually exists", "money": "0", "time": "low", "willpower": "no", "benefit": "low", "dimension": "time", "evidence": "B (documented institutional difference in research/law-substitution.md)", "grade": "B", "disputed": false, "cost": "$0 (2026). The time to look up the right number once.", "plain": "No neighbourhood committee will mediate your dispute; no women's federation will intervene. Noisy neighbour, condo conflict: 311, the condo board, Small Claims Court. Women's safety: a shelter, a helpline, 911. Going to the right place first saves weeks.", "benefit_text": "Time saved once (2026): contacting 311, the condo board, a community legal clinic, a shelter, police directly (911 for emergencies), instead of searching for bodies that do not exist in Canada.", "sources": "https://www.ontario.ca/page/consumer-protection-ontario", "notes": "", "urls": ["https://www.ontario.ca/page/consumer-protection-ontario"]}, {"id": "08-020", "chapter_num": 8, "chapter_title": "Don't get entangled (trouble with others)", "chapter_file": "08-dont-get-entangled.md", "number": 20, "title": "Keep your dog under control — owners are strictly liable for bites", "money": "low", "time": "low", "willpower": "some", "benefit": "low", "dimension": "freedom", "evidence": "B (statute rule quoted verbatim in substance)", "grade": "B", "disputed": false, "cost": "Low (2026): a leash, training time, and the willpower to restrain a friendly dog around strangers.", "plain": "In Ontario, if your dog bites, attacks, you are liable — no one has to prove you knew the dog was dangerous. \"He never did this before\" is not a defence.", "benefit_text": "\"The owner of a dog is liable for damages resulting from a bite or attack by the dog on another person\" with no need to prove the owner knew of any propensity (Dog Owners' Liability Act, s.2, 2026).", "sources": "https://ontario.ca/laws/statute/90d16/v1", "notes": "", "urls": ["https://ontario.ca/laws/statute/90d16/v1"]}, {"id": "08-021", "chapter_num": 8, "chapter_title": "Don't get entangled (trouble with others)", "chapter_file": "08-dont-get-entangled.md", "number": 21, "title": "If you cannot afford a lawyer, check legal aid before giving up", "money": "0", "time": "mid", "willpower": "no", "benefit": "mid", "dimension": "money", "evidence": "B (official program rules stated as fact)", "grade": "B", "disputed": false, "cost": "$0 (2026). An application and a wait of days to weeks; eligibility is income- and asset-tested.", "plain": "Legal aid is the difference between facing court alone and facing it with a lawyer. Ontario: Legal Aid Ontario. Quebec: the Commission des services juridiques. Check the thresholds — you may qualify even with a job.", "benefit_text": "A legal-aid certificate covers a lawyer's fees in criminal and family matters (2026). Legal Aid Ontario: income below $45,440 for families of 1–4 and assets below $15,000. Quebec CSJ: single-person income at or below $29,302/year, assets at or below $47,500 (non-homeowner) or $90,000 (homeowner), liquidities at or below $2,500 (single) or $5,000 (family); contributory aid $100–$800.", "sources": "https://www.legalaid.on.ca/wp-content/uploads/Factsheet-LAO-Can-Help.pdf https://www.csj.qc.ca", "notes": "Graded mid (judgment call per §5): a criminal or family certificate is worth thousands of dollars in legal fees — inside the $5,000–$50,000 band. Thresholds indexed 2025–2026; re-check at application time.", "urls": ["https://www.csj.qc.ca", "https://www.legalaid.on.ca/wp-content/uploads/Factsheet-LAO-Can-Help.pdf"]}, {"id": "08-022", "chapter_num": 8, "chapter_title": "Don't get entangled (trouble with others)", "chapter_file": "08-dont-get-entangled.md", "number": 22, "title": "Small claims: know the ceiling before you file", "money": "low", "time": "mid", "willpower": "no", "benefit": "mid", "dimension": "money", "evidence": "B (official court rules stated as fact)", "grade": "B", "disputed": false, "cost": "Low (2026): a filing fee and an evening of paperwork; a hearing months later.", "plain": "Ontario: Small Claims Court hears cases up to $50,000 (from 1 Oct 2025). Quebec: the small-claims division hears cases up to $15,000. Above the ceiling, you need a lawyer and a higher court — file in the right place the first time.", "benefit_text": "Ontario: up to $50,000 per claim (from 1 Oct 2025). Quebec: up to $15,000 per claim (2026). Filing within the ceiling keeps the procedure simple and lawyer-optional.", "sources": "https://www.ontario.ca/page/suing-someone-small-claims-court", "notes": "Two clearly labelled halves per §7.2. Graded mid (judgment call per §5): a successful claim recovers up to the ceiling — inside the $5,000–$50,000 band.", "urls": ["https://www.ontario.ca/page/suing-someone-small-claims-court"]}, {"id": "08-023", "chapter_num": 8, "chapter_title": "Don't get entangled (trouble with others)", "chapter_file": "08-dont-get-entangled.md", "number": 23, "title": "Limitation clocks run out — Ontario 2 years, Quebec 3 years", "money": "0", "time": "low", "willpower": "no", "benefit": "low", "dimension": "freedom", "evidence": "B (statute rules stated as fact)", "grade": "B", "disputed": false, "cost": "$0 (2026). The discipline to act instead of waiting.", "plain": "Ontario: you generally have 2 years from when you discovered the claim. Quebec: 3 years. Miss the clock and the claim dies no matter how strong it was. When something goes wrong, get advice early — the clock starts running before you feel ready.", "benefit_text": "Ontario: 2 years from discovery (Limitations Act, 2002, s.4, 2026). Quebec: 3 years (Civil Code, art.2925, 2026). Exceptions exist (e.g. no limitation for sexual assault in Ontario), but the default clock is strict.", "sources": "https://www.ontario.ca/laws/statute/02l24 https://www.legisquebec.gouv.qc.ca/fr/document/lc/C-25.1/20200317?langCont=en", "notes": "Two clearly labelled halves per §7.2. Mechanical grade low (avoids losing a civil claim).", "urls": ["https://www.legisquebec.gouv.qc.ca/fr/document/lc/C-25.1/20200317?langCont=en", "https://www.ontario.ca/laws/statute/02l24"]}, {"id": "08-024", "chapter_num": 8, "chapter_title": "Don't get entangled (trouble with others)", "chapter_file": "08-dont-get-entangled.md", "number": 24, "title": "For consumer problems: complain in writing, then escalate to the province", "money": "0", "time": "low", "willpower": "no", "benefit": "low", "dimension": "money", "evidence": "B (official program information stated as fact)", "grade": "B", "disputed": false, "cost": "$0 (2026). An hour to write a dated complaint with receipts attached.", "plain": "Ontario: complain to the business in writing first, then to Consumer Protection Ontario, 1-800-889-9768. Quebec: the Office de la protection du consommateur. A dated paper trail is the prerequisite — \"I called twice\" is not.", "benefit_text": "Consumer Protection Ontario: 1-800-889-9768 (2026). Quebec: Office de la protection du consommateur, opc.gouv.qc.ca (2026). Written complaints with receipts are investigated; verbal ones usually are not.", "sources": "https://www.ontario.ca/page/consumer-protection-ontario https://www.opc.gouv.qc.ca/mes-droits-consommateur/", "notes": "Two clearly labelled halves per §7.2.", "urls": ["https://www.ontario.ca/page/consumer-protection-ontario", "https://www.opc.gouv.qc.ca/mes-droits-consommateur/"]}, {"id": "08-025", "chapter_num": 8, "chapter_title": "Don't get entangled (trouble with others)", "chapter_file": "08-dont-get-entangled.md", "number": 25, "title": "Never offer a public official money or gifts for a decision", "money": "0", "time": "low", "willpower": "some", "benefit": "high", "dimension": "freedom", "evidence": "B (statute rules stated as fact)", "grade": "B", "disputed": false, "cost": "$0 (2026). The gift money stays in your pocket; some willpower where gift-giving was once normal.", "plain": "What reads as politeness, \"relationship-building\" elsewhere reads as bribery here. Never offer cash, gifts, favours to an official, inspector, police officer in exchange for a decision.", "benefit_text": "Bribing or attempting to bribe a public official is a criminal offence (ss.120–122, 2026) — no minimum gift value, no cultural exception.", "sources": "https://laws-lois.justice.gc.ca/eng/acts/c-46/section-120.html", "notes": "", "urls": ["https://laws-lois.justice.gc.ca/eng/acts/c-46/section-120.html"]}, {"id": "08-026", "chapter_num": 8, "chapter_title": "Don't get entangled (trouble with others)", "chapter_file": "08-dont-get-entangled.md", "number": 26, "title": "At the border, never carry packages for strangers — and never bring cannabis across", "money": "0", "time": "low", "willpower": "some", "benefit": "high", "dimension": "freedom", "evidence": "B (statute rules stated as fact)", "grade": "B", "disputed": false, "cost": "$0 (2026). Some willpower to refuse a \"small favour\" at the airport or border crossing.", "plain": "\"Just take this bag across, I'll pay you\" is how couriers are recruited. You own everything in your luggage under the law. Cannabis is legal inside Canada and contraband the moment it crosses the border — in either direction.", "benefit_text": "Carrying drugs across the border for anyone is trafficking under the Controlled Drugs and Substances Act (2026). Importing or exporting cannabis without federal authorization is prohibited (Cannabis Act, s.46, 2026). CBSA Border Watch: 1-888-502-9060.", "sources": "https://laws-lois.justice.gc.ca/eng/acts/C-24.5/page-1.html", "notes": "", "urls": ["https://laws-lois.justice.gc.ca/eng/acts/C-24.5/page-1.html"]}, {"id": "09-001", "chapter_num": 9, "chapter_title": "Legal red lines ordinary people cross", "chapter_file": "09-legal-red-lines.md", "number": 1, "title": "Don't defraud anyone — the $5,000 line decides the sentence", "money": "0", "time": "low", "willpower": "some", "benefit": "high", "dimension": "freedom", "evidence": "B (statute rules stated as fact)", "grade": "B", "disputed": false, "cost": "$0 (2026). Some willpower to walk away from \"easy money\" schemes — fake invoices, benefit lies, platform rebate tricks.", "plain": "Fraud is fraud whether the victim is a person, a company, the government. Above $5,000 the maximum is 14 years; above $1,000,000 there is a 2-year minimum. The amount is what the court counts, not what you intended.", "benefit_text": "Fraud over $5,000: up to 14 years (s.380(1)(a), 2026). Fraud of $5,000 or less: up to 2 years indictable (s.380(1)(b), 2026). Fraud over $1,000,000: a 2-year minimum sentence (s.380(1.1), 2026).", "sources": "https://laws-lois.justice.gc.ca/eng/acts/c-46/section-380.html", "notes": "", "urls": ["https://laws-lois.justice.gc.ca/eng/acts/c-46/section-380.html"]}, {"id": "09-002", "chapter_num": 9, "chapter_title": "Legal red lines ordinary people cross", "chapter_file": "09-legal-red-lines.md", "number": 2, "title": "Murder means life in prison — Canada has no death penalty", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "freedom", "evidence": "B (statute rules stated as fact)", "grade": "B", "disputed": false, "cost": "$0 (2026). Nothing to do — this item exists to correct a dangerous assumption.", "plain": "Canada abolished the death penalty decades ago; the maximum punishment is life imprisonment, and for first-degree murder there is no parole for 25 years. No crime, however serious, changes that — and no private \"revenge\" is lawful either.", "benefit_text": "Murder is defined in s.229 and punished with imprisonment for life (s.235, 2026). First-degree murder: life without eligibility for parole for 25 years (s.745(a), 2026).", "sources": "https://laws-lois.justice.gc.ca/eng/acts/c-46/section-235.html https://laws-lois.justice.gc.ca/eng/acts/c-46/section-745.html", "notes": "", "urls": ["https://laws-lois.justice.gc.ca/eng/acts/c-46/section-235.html", "https://laws-lois.justice.gc.ca/eng/acts/c-46/section-745.html"]}, {"id": "09-003", "chapter_num": 9, "chapter_title": "Legal red lines ordinary people cross", "chapter_file": "09-legal-red-lines.md", "number": 3, "title": "Sexual assault carries 10 to 14 years — consent has hard legal boundaries", "money": "0", "time": "low", "willpower": "some", "benefit": "high", "dimension": "freedom", "evidence": "B (statute rules stated as fact)", "grade": "B", "disputed": false, "cost": "$0 (2026). Some willpower to stop and check when the situation is ambiguous.", "plain": "The baseline is 10 years, rising to 14 where the complainant is under 16. Consent must be real and ongoing — and under 16, consent is simply not a defence, with only narrow close-in-age exceptions.", "benefit_text": "Sexual assault: up to 10 years (s.271, 2026); 14 years with a 1-year minimum where the complainant is under 16. Consent is no defence under 16 (s.150.1, 2026); close-in-age exceptions: 12–13 with a partner less than 2 years older, 14–15 with a partner less than 5 years older; never under trust, authority, or dependency.", "sources": "https://laws-lois.justice.gc.ca/eng/acts/c-46/section-271.html https://laws-lois.justice.gc.ca/eng/acts/c-46/section-150.1.html", "notes": "", "urls": ["https://laws-lois.justice.gc.ca/eng/acts/c-46/section-150.1.html", "https://laws-lois.justice.gc.ca/eng/acts/c-46/section-271.html"]}, {"id": "09-004", "chapter_num": 9, "chapter_title": "Legal red lines ordinary people cross", "chapter_file": "09-legal-red-lines.md", "number": 4, "title": "Impaired driving is criminal at 80 mg — there is no warning tier", "money": "0", "time": "low", "willpower": "yes", "benefit": "high", "dimension": "freedom", "evidence": "B (statute rule stated as fact)", "grade": "B", "disputed": false, "cost": "$0–$40 (2026). The ride home, arranged before drinking starts; real willpower to hand over the keys.", "plain": "Canada has no two-tier system for drink versus drunk driving. At 80 mg of alcohol per 100 mL of blood within 2 hours of driving, it is a criminal offence — full stop. Drugs count the same as alcohol.", "benefit_text": "Driving with 80 mg or more of alcohol per 100 mL of blood within 2 hours is a criminal offence (s.320.14, 2026). No drink-versus-drunk two-tier system exists in Canadian law.", "sources": "https://laws-lois.justice.gc.ca/eng/acts/c-46/section-320.14.html", "notes": "", "urls": ["https://laws-lois.justice.gc.ca/eng/acts/c-46/section-320.14.html"]}, {"id": "09-005", "chapter_num": 9, "chapter_title": "Legal red lines ordinary people cross", "chapter_file": "09-legal-red-lines.md", "number": 5, "title": "Don't hit, threaten, or stalk — the penalties stack by severity", "money": "0", "time": "low", "willpower": "yes", "benefit": "high", "dimension": "freedom", "evidence": "B (statute rules stated as fact)", "grade": "B", "disputed": false, "cost": "$0 (2026). Real willpower to walk away from provocation.", "plain": "A punch is 5 years; a weapon, an injury, takes it to 10; serious wounding is 14. Threatening to kill is 5 years on its own; stalking — including tracking someone's location — is 10. Anger is not a defence to any of it.", "benefit_text": "Assault: up to 5 years (s.266, 2026). Assault with a weapon or causing bodily harm: up to 10 years (s.267, 2026). Aggravated assault: up to 14 years (s.268, 2026). Uttering threats of death or bodily harm: up to 5 years (s.264.1, 2026). Criminal harassment: up to 10 years (s.264, 2026).", "sources": "https://laws-lois.justice.gc.ca/eng/acts/c-46/section-266.html https://laws-lois.justice.gc.ca/eng/acts/c-46/section-267.html https://laws-lois.justice.gc.ca/eng/acts/c-46/section-268.html", "notes": "", "urls": ["https://laws-lois.justice.gc.ca/eng/acts/c-46/section-266.html", "https://laws-lois.justice.gc.ca/eng/acts/c-46/section-267.html", "https://laws-lois.justice.gc.ca/eng/acts/c-46/section-268.html"]}, {"id": "09-006", "chapter_num": 9, "chapter_title": "Legal red lines ordinary people cross", "chapter_file": "09-legal-red-lines.md", "number": 6, "title": "Don't extort — threats for money or images can mean life in prison", "money": "0", "time": "low", "willpower": "some", "benefit": "high", "dimension": "freedom", "evidence": "B (statute rules stated as fact)", "grade": "B", "disputed": false, "cost": "$0 (2026). Some willpower to take a dispute to court instead of squeezing the other side.", "plain": "Threatening someone to get money, property, compliance is extortion — maximum life imprisonment. Threatening to publish intimate images is 10 years on its own. One exception the law keeps: threatening to file a legitimate civil lawsuit is not extortion.", "benefit_text": "Extortion: up to life imprisonment (s.346(1.1)(b), 2026). Threatening to publish an intimate image: up to 10 years (s.162.1(1.1), 2026). Threatening to institute civil proceedings is not a threat for this offence (s.346(2), 2026).", "sources": "https://laws-lois.justice.gc.ca/eng/acts/c-46/section-346.html https://laws-lois.justice.gc.ca/eng/acts/c-46/section-162.1.html", "notes": "", "urls": ["https://laws-lois.justice.gc.ca/eng/acts/c-46/section-162.1.html", "https://laws-lois.justice.gc.ca/eng/acts/c-46/section-346.html"]}, {"id": "09-007", "chapter_num": 9, "chapter_title": "Legal red lines ordinary people cross", "chapter_file": "09-legal-red-lines.md", "number": 7, "title": "Never make, share, keep, or view sexual images of anyone under 18", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "freedom", "evidence": "B (statute rules stated as fact)", "grade": "B", "disputed": false, "cost": "$0 (2026). No precaution beyond never touching this material in any form.", "plain": "The law calls it child sexual abuse and exploitation material. Making, distributing it is 14 years; even possessing, accessing it is 10 years with a 1-year minimum. \"I only looked,\" \"someone sent it to me\" — neither is a defence. Delete and report.", "benefit_text": "Possession or access: up to 10 years with a 1-year minimum (s.163.1, 2026). Making, transmitting, or distributing: up to 14 years with a 1-year minimum. The statute now uses the term \"child sexual abuse and exploitation material.\"", "sources": "https://laws-lois.justice.gc.ca/eng/acts/c-46/section-163.1.html", "notes": "", "urls": ["https://laws-lois.justice.gc.ca/eng/acts/c-46/section-163.1.html"]}, {"id": "09-008", "chapter_num": 9, "chapter_title": "Legal red lines ordinary people cross", "chapter_file": "09-legal-red-lines.md", "number": 8, "title": "Don't record or share intimate images without consent — AI fakes count too", "money": "0", "time": "low", "willpower": "some", "benefit": "high", "dimension": "freedom", "evidence": "B (statute rules stated as fact)", "grade": "B", "disputed": false, "cost": "$0 (2026). Some willpower to delete instead of forwarding.", "plain": "Recording someone naked, sexual, without their knowledge is voyeurism. Publishing, sharing an intimate image without the depicted person's consent is 10 years — and AI-generated likenesses count as intimate images under the law.", "benefit_text": "Publishing an intimate image without consent: up to 10 years (s.162.1, 2026); the offence covers AI-generated likenesses (s.162.1(2)(b), 2026). Voyeurism — surreptitious observation or recording — is a separate offence (s.162, 2026).", "sources": "https://laws-lois.justice.gc.ca/eng/acts/c-46/section-162.1.html https://laws-lois.justice.gc.ca/eng/acts/c-46/section-162.html", "notes": "", "urls": ["https://laws-lois.justice.gc.ca/eng/acts/c-46/section-162.1.html", "https://laws-lois.justice.gc.ca/eng/acts/c-46/section-162.html"]}, {"id": "09-009", "chapter_num": 9, "chapter_title": "Legal red lines ordinary people cross", "chapter_file": "09-legal-red-lines.md", "number": 9, "title": "Don't steal — the $5,000 line decides the sentence here too", "money": "0", "time": "low", "willpower": "some", "benefit": "high", "dimension": "freedom", "evidence": "B (statute rules stated as fact)", "grade": "B", "disputed": false, "cost": "$0 (2026). Some willpower at the self-checkout and the warehouse club.", "plain": "Theft over $5,000 is 10 years; $5,000 and under is 2 years indictable. Shoplifting, \"forgetting\" to scan, taking from an employer are all theft — the amount is what the court counts.", "benefit_text": "Theft over $5,000: up to 10 years (s.334(a), 2026). Theft of $5,000 or less: up to 2 years indictable (s.334(b), 2026).", "sources": "https://laws-lois.justice.gc.ca/eng/acts/c-46/section-334.html", "notes": "", "urls": ["https://laws-lois.justice.gc.ca/eng/acts/c-46/section-334.html"]}, {"id": "09-010", "chapter_num": 9, "chapter_title": "Legal red lines ordinary people cross", "chapter_file": "09-legal-red-lines.md", "number": 10, "title": "Don't use someone else's identity — and don't hand yours over", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "freedom", "evidence": "B (statute rules stated as fact)", "grade": "B", "disputed": false, "cost": "$0 (2026). Nothing beyond refusing to share or borrow identity documents.", "plain": "Using another person's ID, SIN, bank details is 5 to 10 years depending on the charge. Lending your own identity to a \"friend\" makes you the accomplice. Neither direction is safe.", "benefit_text": "Identity theft: up to 5 years (s.402.2(1), 2026). Trafficking in identity information: up to 5 years (s.402.2(2), 2026). Identity fraud: up to 10 years (s.403, 2026).", "sources": "https://laws-lois.justice.gc.ca/eng/acts/c-46/section-402.2.html https://laws-lois.justice.gc.ca/eng/acts/c-46/section-403.html", "notes": "", "urls": ["https://laws-lois.justice.gc.ca/eng/acts/c-46/section-402.2.html", "https://laws-lois.justice.gc.ca/eng/acts/c-46/section-403.html"]}, {"id": "09-011", "chapter_num": 9, "chapter_title": "Legal red lines ordinary people cross", "chapter_file": "09-legal-red-lines.md", "number": 11, "title": "No gun without a licence — and a replica used as a weapon is a weapon", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "freedom", "evidence": "B (statute rules stated as fact)", "grade": "B", "disputed": false, "cost": "$0 (2026). Nothing beyond not possessing what you are not licensed for.", "plain": "Possessing a firearm without a licence is 5 years. A replica is a prohibited device — and pointing one at someone is assault with a weapon: 10 years. \"It's not real\" is not a defence once it is used to threaten.", "benefit_text": "Unauthorized possession of a firearm: up to 5 years; a licence is required (s.91, 2026). A replica firearm is a prohibited device (s.84(1), 2026); using an imitation firearm as a weapon is assault with a weapon: up to 10 years (s.267(a), 2026).", "sources": "https://laws-lois.justice.gc.ca/eng/acts/c-46/section-91.html https://laws-lois.justice.gc.ca/eng/acts/c-46/section-84.html", "notes": "", "urls": ["https://laws-lois.justice.gc.ca/eng/acts/c-46/section-84.html", "https://laws-lois.justice.gc.ca/eng/acts/c-46/section-91.html"]}, {"id": "09-012", "chapter_num": 9, "chapter_title": "Legal red lines ordinary people cross", "chapter_file": "09-legal-red-lines.md", "number": 12, "title": "Cannabis: 19+ in Ontario, 21+ in Quebec — and never across the border", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "freedom", "evidence": "B (statute rules stated as fact)", "grade": "B", "disputed": false, "cost": "$0 (2026). Nothing beyond respecting the age and the 30-gram public limit.", "plain": "Ontario: legal at 19. Quebec: legal at 21. Adults may carry up to 30 grams in public, grow up to 4 non-budding plants. Over the limits, unlicensed selling, any border crossing with cannabis is criminal.", "benefit_text": "18+ may possess up to 30 g dried equivalent in public and cultivate up to 4 non-budding plants (Cannabis Act, s.8, 2026). Ontario sets the legal age at 19; Quebec at 21 (2026). Over-limit possession: up to 5 years less a day or a $5,000 fine, or 6 months on summary conviction. Import/export without federal authorization is prohibited (s.46, 2026).", "sources": "https://laws-lois.justice.gc.ca/eng/acts/C-24.5/page-1.html", "notes": "Two clearly labelled halves per §7.2 (federal floor 18 vs Ontario 19 vs Quebec 21).", "urls": ["https://laws-lois.justice.gc.ca/eng/acts/C-24.5/page-1.html"]}, {"id": "09-013", "chapter_num": 9, "chapter_title": "Legal red lines ordinary people cross", "chapter_file": "09-legal-red-lines.md", "number": 13, "title": "Other drugs stay criminal — possession, trafficking, and production", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "freedom", "evidence": "B (statute stated as fact)", "grade": "B", "disputed": false, "cost": "$0 (2026). Nothing beyond not possessing, making, or moving controlled drugs.", "plain": "Cannabis is the exception, not the precedent. Cocaine, heroin, methamphetamine, MDMA, and unprescribed opioids remain criminal under federal law — possession, trafficking, and production alike.", "benefit_text": "Possession, trafficking, and production of controlled substances remain criminal offences under the Controlled Drugs and Substances Act (2026).", "sources": "https://laws-lois.justice.gc.ca/eng/acts/c-38.8/", "notes": "", "urls": ["https://laws-lois.justice.gc.ca/eng/acts/c-38.8/"]}, {"id": "09-014", "chapter_num": 9, "chapter_title": "Legal red lines ordinary people cross", "chapter_file": "09-legal-red-lines.md", "number": 14, "title": "Drones 250 g or more: register and get the pilot certificate first", "money": "low", "time": "mid", "willpower": "no", "benefit": "mid", "dimension": "freedom", "evidence": "B (official regulator rule stated as fact)", "grade": "B", "disputed": false, "cost": "Low (2026). The registration and the basic pilot exam, plus study time.", "plain": "At 250 grams and up, a drone must be registered with Transport Canada, flown by a certificated pilot, under the Canadian Aviation Regulations Part IX. Flying unregistered, uncertified risks fines and seizure of the drone.", "benefit_text": "Drones weighing 250 g or more must be registered and operated with a Transport Canada pilot certificate (CARs Part IX, 2026); non-compliance risks administrative fines and seizure.", "sources": "https://tc.canada.ca/en/aviation/drone-safety/drone-zone/drone-zone-issue-7-may-2026", "notes": "Graded mid (judgment call per §5): avoids administrative fines and seizure — a fine-level outcome.", "urls": ["https://tc.canada.ca/en/aviation/drone-safety/drone-zone/drone-zone-issue-7-may-2026"]}, {"id": "09-015", "chapter_num": 9, "chapter_title": "Legal red lines ordinary people cross", "chapter_file": "09-legal-red-lines.md", "number": 15, "title": "Don't throw objects from balconies or windows", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "freedom", "evidence": "B (statute rule stated as fact)", "grade": "B", "disputed": false, "cost": "$0 (2026). Nothing beyond not doing it.", "plain": "A thrown bottle, a dropped object that endangers life is mischief — maximum life imprisonment. High-rise littering is not a bylaw ticket when someone could be killed.", "benefit_text": "Mischief causing actual danger to life: up to life imprisonment (s.430(2), 2026).", "sources": "https://laws-lois.justice.gc.ca/eng/acts/c-46/section-430.html", "notes": "", "urls": ["https://laws-lois.justice.gc.ca/eng/acts/c-46/section-430.html"]}, {"id": "09-016", "chapter_num": 9, "chapter_title": "Legal red lines ordinary people cross", "chapter_file": "09-legal-red-lines.md", "number": 16, "title": "Gamble only with provincially licensed operators", "money": "0", "time": "low", "willpower": "some", "benefit": "mid", "dimension": "freedom", "evidence": "B (statute rules stated as fact)", "grade": "B", "disputed": false, "cost": "$0 (2026). Some willpower to skip the unlicensed game or website.", "plain": "Keeping an unlicensed gaming house is 2 years; even being found in one is an offence. Online, only provincially licensed operators are legal — the offshore site advertising to you is not.", "benefit_text": "Keeping a common gaming or betting house: up to 2 years (s.201, 2026); being found in one is a summary offence. Only provincially licensed gambling is lawful.", "sources": "https://laws-lois.justice.gc.ca/eng/acts/c-46/section-201.html", "notes": "Graded mid (judgment call per §5): avoids detention-level offences (keeper) and summary conviction (found-in).", "urls": ["https://laws-lois.justice.gc.ca/eng/acts/c-46/section-201.html"]}, {"id": "09-017", "chapter_num": 9, "chapter_title": "Legal red lines ordinary people cross", "chapter_file": "09-legal-red-lines.md", "number": 17, "title": "Don't pay for sexual services — and never involving anyone under 18", "money": "0", "time": "low", "willpower": "some", "benefit": "high", "dimension": "freedom", "evidence": "B (statute rules stated as fact)", "grade": "B", "disputed": false, "cost": "$0 (2026). Some willpower; the money stays in your pocket.", "plain": "Buying sexual services carries mandatory minimum fines — higher near parks and schools. Where the person is under 18, it is 14 years with a 6-month minimum. There is no legal grey zone here.", "benefit_text": "Obtaining sexual services: minimum fines of $1,000 or $500 for a first offence ($2,000 or $4,000 near parks or schools) (s.286.1, 2026). Where the person is under 18: up to 14 years with a 6-month minimum.", "sources": "https://laws-lois.justice.gc.ca/eng/acts/c-46/section-286.1.html", "notes": "", "urls": ["https://laws-lois.justice.gc.ca/eng/acts/c-46/section-286.1.html"]}, {"id": "09-018", "chapter_num": 9, "chapter_title": "Legal red lines ordinary people cross", "chapter_file": "09-legal-red-lines.md", "number": 18, "title": "Don't lie to police or the courts — perjury, obstruction, and false reports", "money": "0", "time": "low", "willpower": "some", "benefit": "high", "dimension": "freedom", "evidence": "B (statute rules stated as fact)", "grade": "B", "disputed": false, "cost": "$0 (2026). Some willpower to say \"I don't remember\" or nothing at all, instead of inventing.", "plain": "Lying under oath is perjury: 14 years. Interfering with a case is obstruction: 10 years. Filing a false police report is 5 years. The cover-up is punished harder than most of the things people lie about.", "benefit_text": "Perjury: up to 14 years (ss.131–132, 2026). Obstructing justice: up to 10 years (s.139(2), 2026). Public mischief (false report to police): up to 5 years (s.140, 2026).", "sources": "https://laws-lois.justice.gc.ca/eng/acts/c-46/section-131.html https://laws-lois.justice.gc.ca/eng/acts/c-46/section-139.html https://laws-lois.justice.gc.ca/eng/acts/c-46/section-140.html", "notes": "", "urls": ["https://laws-lois.justice.gc.ca/eng/acts/c-46/section-131.html", "https://laws-lois.justice.gc.ca/eng/acts/c-46/section-139.html", "https://laws-lois.justice.gc.ca/eng/acts/c-46/section-140.html"]}, {"id": "09-019", "chapter_num": 9, "chapter_title": "Legal red lines ordinary people cross", "chapter_file": "09-legal-red-lines.md", "number": 19, "title": "Don't assault or obstruct police officers", "money": "0", "time": "low", "willpower": "yes", "benefit": "high", "dimension": "freedom", "evidence": "B (statute rules stated as fact)", "grade": "B", "disputed": false, "cost": "$0 (2026). Real willpower to keep your hands down and your mouth shut during a stop.", "plain": "Assaulting a peace officer is 5 years; resisting, obstructing is 2 years — on top of whatever the stop was about. Compliance now, complaint later: note the badge number, file a complaint afterward if the stop was improper.", "benefit_text": "Assaulting a peace officer: up to 5 years (s.270, 2026). Resisting or obstructing a peace officer: up to 2 years (s.129(a), 2026).", "sources": "https://laws-lois.justice.gc.ca/eng/acts/c-46/section-270.html https://laws-lois.justice.gc.ca/eng/acts/c-46/section-129.html", "notes": "", "urls": ["https://laws-lois.justice.gc.ca/eng/acts/c-46/section-129.html", "https://laws-lois.justice.gc.ca/eng/acts/c-46/section-270.html"]}, {"id": "09-020", "chapter_num": 9, "chapter_title": "Legal red lines ordinary people cross", "chapter_file": "09-legal-red-lines.md", "number": 20, "title": "Insurance fraud is fraud — staged accidents mean prison, not payouts", "money": "0", "time": "low", "willpower": "some", "benefit": "high", "dimension": "freedom", "evidence": "B (statute rule; industry practice)", "grade": "B", "disputed": false, "cost": "$0 (2026). Some willpower to refuse the \"easy claim\" a fixer proposes.", "plain": "Staged collisions, inflated repair bills, and fake injury claims are fraud over $5,000 in most cases: 14 years. Insurers share fraud data and prosecute — the payout never arrives, but the criminal record does.", "benefit_text": "Insurance fraud is fraud: over $5,000 means up to 14 years (s.380(1)(a), 2026). Staged accidents also bring civil liability and policy cancellation.", "sources": "https://laws-lois.justice.gc.ca/eng/acts/c-46/section-380.html", "notes": "", "urls": ["https://laws-lois.justice.gc.ca/eng/acts/c-46/section-380.html"]}, {"id": "10-001", "chapter_num": 10, "chapter_title": "Dating and Marriage", "chapter_file": "10-dating-and-marriage.md", "number": 1, "title": "Stop all contact after a clear no", "money": "0", "time": "low", "willpower": "yes", "benefit": "high", "dimension": "freedom", "evidence": "B", "grade": "B", "disputed": false, "cost": "No money; the hard part is accepting the answer and walking away.", "plain": "After someone has clearly refused you, every further message, every visit, every attempt to watch them makes things worse for both of you and can turn a bad breakup into a criminal file. Stop all contact, keep any threats made against you as evidence, and call the police if you feel unsafe.", "benefit_text": "Repeatedly following, communicating with, watching, or threatening someone after a refusal is criminal harassment, punishable by up to ten years in prison. If you are the one being harassed, a court can order the other person to keep the peace for up to twelve months.", "sources": "Criminal Code s.264 — https://laws-lois.justice.gc.ca/eng/acts/c-46/section-264.html?wbdisable=true ; s.810 peace bond — https://laws-lois.justice.gc.ca/eng/acts/c-46/section-810.html", "notes": "", "urls": ["https://laws-lois.justice.gc.ca/eng/acts/c-46/section-264.html?wbdisable=true", "https://laws-lois.justice.gc.ca/eng/acts/c-46/section-810.html"]}, {"id": "10-002", "chapter_num": 10, "chapter_title": "Dating and Marriage", "chapter_file": "10-dating-and-marriage.md", "number": 2, "title": "Learn the default money rules before marrying; put your own rules in writing", "money": "low", "time": "mid", "willpower": "some", "benefit": "high", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "A domestic contract drafted with a lawyer, plus one honest conversation about money.", "plain": "Marriage in Canada is a financial contract with default rules you cannot opt out of by staying silent. In Ontario the spouse whose wealth grew more during the marriage owes the other half the difference. In Quebec a defined set of family assets is shared no matter whose name is on the title. Living together without marrying gives you almost none of this protection. Decide the money rules in writing before the wedding, not during the divorce.", "benefit_text": "Ontario's Family Law Act gives the spouse with the smaller net family property one-half the difference on separation or divorce. A written domestic contract lets a couple set different rules in advance.", "sources": "Family Law Act, R.S.O. 1990, c. F.3, s.5 — https://www.ontario.ca/laws/statute/90f03", "notes": "Quebec: the family patrimony (CCQ arts. 414–426) shares the net value of the family home, household goods, and pension accruals equally; the default matrimonial regime is société d'acquêts. In both provinces, unmarried partners get no property sharing and no intestacy rights. See docs/verification/10-dating-and-marriage.md.", "urls": ["https://www.ontario.ca/laws/statute/90f03"]}, {"id": "10-003", "chapter_num": 10, "chapter_title": "Dating and Marriage", "chapter_file": "10-dating-and-marriage.md", "number": 3, "title": "Write down whether parental money is a gift or a loan at the moment it changes hands", "money": "0", "time": "low", "willpower": "some", "benefit": "high", "dimension": "money", "evidence": "C", "grade": "C", "disputed": false, "cost": "One dated page signed by everyone involved; no money.", "plain": "When parents contribute to a down payment, write down on the spot whether it is a gift, whether it is a loan, who it is for, and whether it must be repaid. Memory fades, and divorces turn vague generosity into lawsuits about money that was never documented.", "benefit_text": "A signed note made at transfer time is the best evidence of what the money was; without it, the same transfer can be claimed as a joint asset or a repayable debt years later.", "sources": "UNVERIFIED — the \"best evidence\" claim is legal-practice advice with no citable primary source found in this edition. Background only: Family Law Act, RSO 1990, c. F.3. <https://www.ontario.ca/laws/statute/90f03> (does not state this claim). See docs/verification/spot-read.md.", "notes": "", "urls": ["https://www.ontario.ca/laws/statute/90f03"]}, {"id": "10-004", "chapter_num": 10, "chapter_title": "Dating and Marriage", "chapter_file": "10-dating-and-marriage.md", "number": 4, "title": "Do not co-sign or take on a partner's debts", "money": "0", "time": "low", "willpower": "yes", "benefit": "high", "dimension": "money", "evidence": "C", "grade": "C", "disputed": false, "cost": "Free; the price is saying no to someone you love.", "plain": "If you did not sign for a debt, it is not yours. Never co-sign a loan to prove your love. Never co-sign a credit card either. And never agree in writing to take over a partner's borrowing. Love fades; the signature stays.", "benefit_text": "Keeps your credit and savings separate from a partner's spending; one co-signature can make you liable for the entire balance.", "sources": "Family Law Act, RSO 1990, c. F.3 (background only — <https://www.ontario.ca/laws/statute/90f03>); the co-signature liability claim is grade-C general practice, not a proposition this statute states. See docs/verification/spot-read.md.", "notes": "", "urls": ["https://www.ontario.ca/laws/statute/90f03"]}, {"id": "10-005", "chapter_num": 10, "chapter_title": "Dating and Marriage", "chapter_file": "10-dating-and-marriage.md", "number": 5, "title": "Meet more people instead of fixating on one", "money": "0", "time": "mid", "willpower": "some", "benefit": "high", "dimension": "time", "evidence": "A", "grade": "A", "disputed": false, "cost": "Time and repeated small rejections; no money.", "plain": "Whether you click with someone is very hard to predict before you meet them, so the bottleneck is how many new people you actually encounter. Regular social routines, hobbies, and friends of friends beat waiting in place and swiping harder.", "benefit_text": "Research on initial attraction finds romantic desire is poorly predictable from profiles and stated preferences; exposure is the factor most people can actually change.", "sources": "Joel S, Eastwick PW, Finkel EJ (2017), Psychological Science — https://doi.org/10.1177/0956797617714580 ; Eastwick PW, Finkel EJ (2008), J. Personality and Social Psychology — https://doi.org/10.1037/0022-3514.94.2.245", "notes": "", "urls": ["https://doi.org/10.1037/0022-3514.94.2.245", "https://doi.org/10.1177/0956797617714580"]}, {"id": "10-006", "chapter_num": 10, "chapter_title": "Dating and Marriage", "chapter_file": "10-dating-and-marriage.md", "number": 6, "title": "Judge interest by behavior, not by signals", "money": "0", "time": "low", "willpower": "some", "benefit": "high", "dimension": "time", "evidence": "B", "grade": "B", "disputed": false, "cost": "Attention and honesty; no money.", "plain": "People are bad at reading flirting and tend to see interest where there is none. Watch what the other person does instead: who initiates, who makes plans, who follows through. Consistent effort is interest; everything else is noise.", "benefit_text": "Flirting-detection research shows systematic over-perception of interest; tracking concrete behavior avoids months spent decoding mixed signals.", "sources": "Hall JA, Xing C, Brooks S (2015), Communication Research — https://doi.org/10.1177/0093650214534972", "notes": "", "urls": ["https://doi.org/10.1177/0093650214534972"]}, {"id": "10-007", "chapter_num": 10, "chapter_title": "Dating and Marriage", "chapter_file": "10-dating-and-marriage.md", "number": 7, "title": "Rate the relationship by how you feel in it", "money": "0", "time": "low", "willpower": "some", "benefit": "high", "dimension": "time", "evidence": "A", "grade": "A", "disputed": false, "cost": "Honest self-reflection; no money.", "plain": "The best predictor of whether a relationship lasts is your own day-to-day experience of it — how secure, appreciated, and at ease you feel — not the other person's resume, looks, income. If your own read is consistently bad, believe it.", "benefit_text": "A synthesis of dozens of long-term couples studies found people's own reports of relationship quality were the most robust predictors of how the relationship would fare.", "sources": "Joel S, Eastwick PW, Allison CJ, et al. (2020), PNAS — https://doi.org/10.1073/pnas.1917036117", "notes": "", "urls": ["https://doi.org/10.1073/pnas.1917036117"]}, {"id": "10-008", "chapter_num": 10, "chapter_title": "Dating and Marriage", "chapter_file": "10-dating-and-marriage.md", "number": 8, "title": "Count the health link, but discount it", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "death", "evidence": "A (disputed)", "grade": "A", "disputed": true, "cost": "Nothing; a change of perspective.", "plain": "Married people tend to live longer than unmarried people in large population studies, but marriage itself gets only part of the credit — healthier and wealthier people are also more likely to marry. Treat a good marriage as a health bonus, not a health plan, and never stay in a bad one for the numbers.", "benefit_text": "Multiple large reviews link being married with lower mortality, but the studies are observational and cannot fully separate selection from causation; a bad marriage shows no such advantage.", "sources": "Manzoli L, et al. (2007), Social Science & Medicine — https://doi.org/10.1016/j.socscimed.2006.08.031 ; Roelfs DJ, et al. (2011), American J. Epidemiology — https://doi.org/10.1093/aje/kwr111 ; Wang Y, et al. (2020), Global Health Research and Policy — https://doi.org/10.1186/s41256-020-00133-8", "notes": "Counter-evidence: the association shrinks or disappears once income, baseline health, and relationship quality are accounted for, and several studies find no advantage for unhappily married people. Correlation is not causation here.", "urls": ["https://doi.org/10.1016/j.socscimed.2006.08.031", "https://doi.org/10.1093/aje/kwr111", "https://doi.org/10.1186/s41256-020-00133-8"]}, {"id": "10-009", "chapter_num": 10, "chapter_title": "Dating and Marriage", "chapter_file": "10-dating-and-marriage.md", "number": 9, "title": "Weigh relationship quality as a health factor", "money": "0", "time": "low", "willpower": "some", "benefit": "high", "dimension": "death", "evidence": "B (disputed)", "grade": "B", "disputed": true, "cost": "The ongoing work of a decent relationship; no money.", "plain": "It is not the marriage certificate that matters for health but how the marriage feels. Warm, supportive partnerships are linked with better health; hostile, contemptuous ones are linked with worse. Quality, not status, is the variable.", "benefit_text": "Reviews link higher marital quality with better cardiovascular and immune markers, while hostile conflict is linked with slower wound healing and higher inflammation.", "sources": "Robles TF, et al. (2014), Psychological Bulletin — https://doi.org/10.1037/a0031859 ; Dhindsa DS, et al. (2020), Trends in Cardiovascular Medicine — https://doi.org/10.1016/j.tcm.2019.05.012", "notes": "Counter-evidence: nearly all studies are observational; shared lifestyle, income, and baseline health explain part of the link, and the direction of causation is debated.", "urls": ["https://doi.org/10.1016/j.tcm.2019.05.012", "https://doi.org/10.1037/a0031859"]}, {"id": "10-010", "chapter_num": 10, "chapter_title": "Dating and Marriage", "chapter_file": "10-dating-and-marriage.md", "number": 10, "title": "Get the paperwork right: licence in Ontario, publication in Quebec", "money": "low", "time": "mid", "willpower": "no", "benefit": "mid", "dimension": "time", "evidence": "B", "grade": "B", "disputed": false, "cost": "A municipal licence fee and a visit to city hall.", "plain": "In Ontario, pick up a marriage licence from any municipal office, hold the ceremony before it expires, and have two witnesses sign. In Quebec, contact the Directeur de l'etat civil well in advance so the mandatory public notice of the marriage can run before the ceremony.", "benefit_text": "Ontario licences are valid for three months from issue and the ceremony requires two witnesses. In Quebec the marriage notice is published online for twenty days before the ceremony can take place.", "sources": "Ontario marriage requirements (Queen's Printer publication) — https://brant.ca/media/5jxjzetn/requirements-respecting-marriage-in-ontario.pdf ; Directeur de l'etat civil — https://etatcivil.gouv.qc.ca/en/default.html", "notes": "", "urls": ["https://brant.ca/media/5jxjzetn/requirements-respecting-marriage-in-ontario.pdf", "https://etatcivil.gouv.qc.ca/en/default.html"]}, {"id": "10-011", "chapter_num": 10, "chapter_title": "Dating and Marriage", "chapter_file": "10-dating-and-marriage.md", "number": 11, "title": "Know that same-sex marriage is legal across Canada", "money": "0", "time": "low", "willpower": "no", "benefit": "mid", "dimension": "freedom", "evidence": "B", "grade": "B", "disputed": false, "cost": "Nothing.", "plain": "Federal law defines civil marriage as the lawful union of two people, with no mention of sex. A same-sex marriage performed in Canada is valid in every province and carries the same property, tax, and immigration rights as any other marriage.", "benefit_text": "Legal nationwide since 2005 under the Civil Marriage Act; no province can refuse to recognize it.", "sources": "Civil Marriage Act, S.C. 2005, c. 33 — https://lois.justice.gc.ca/PDF/C-31.5.pdf", "notes": "", "urls": ["https://lois.justice.gc.ca/PDF/C-31.5.pdf"]}, {"id": "10-012", "chapter_num": 10, "chapter_title": "Dating and Marriage", "chapter_file": "10-dating-and-marriage.md", "number": 12, "title": "Price the exit before you enter: one year apart", "money": "0", "time": "low", "willpower": "no", "benefit": "mid", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "Free to learn; the divorce itself costs money and time.", "plain": "Canada has no quick divorce. The court needs proof the marriage broke down, and the usual proof is living separate and apart for a full year. You can file before the year is up, but the divorce is not granted until the year has run. Price that year of limbo — housing, money, paperwork — before you marry.", "benefit_text": "The Divorce Act requires at least one year of separation for a no-fault divorce; short reconciliation attempts of up to ninety days do not reset the clock.", "sources": "Divorce Act, R.S.C. 1985, c. D-3.4, s.8 — https://laws-lois.justice.gc.ca/eng/acts/d-3.4/fulltext.html", "notes": "A marriage of convenience is still a real marriage: only a divorce ends it, and adultery or cruelty are the only faster grounds.", "urls": ["https://laws-lois.justice.gc.ca/eng/acts/d-3.4/fulltext.html"]}, {"id": "10-013", "chapter_num": 10, "chapter_title": "Dating and Marriage", "chapter_file": "10-dating-and-marriage.md", "number": 13, "title": "If kids are in the picture, settle parenting and support before you sign anything", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "Nothing to learn; a family lawyer costs money if you hire one.", "plain": "A divorce with children is two negotiations, not one: who makes the big decisions for the kids and where they live, plus who pays what. Courts decide parenting by one test only — the best interests of the child. Child support is set by tables, not by haggling: the federal tables apply in divorce cases, except Quebec uses its own support model when both parents live there. Support is the child's right, so a private deal that shortchanges the child can be set aside by a judge. Do not sign a separation agreement about the kids and the money without a family lawyer reading it first — the one you sign in a hurry is the one you live with for years.", "benefit_text": "The Divorce Act makes the child's best interests the only test for parenting orders (s.16); guideline-based support protects the lower-earning parent and the child from lopsided private deals.", "sources": "Divorce Act, R.S.C. 1985, c. D-3.4, ss.15.1, 16 — https://laws-lois.justice.gc.ca/eng/acts/d-3.4/fulltext.html ; Federal Child Support Guidelines, SOR/97-175 — https://laws-lois.justice.gc.ca/eng/regulations/SOR-97-175/FullText.html ; Parenting after separation guide (Quebec support model), Ministère de la Justice du Québec — https://www.justice.gouv.qc.ca/fileadmin/user_upload/contenu/professionnels-securise/EN/parenting/2_Parenting.pdf", "notes": "Since March 2021 the federal law says \"decision-making responsibility\" and \"parenting time\" instead of \"custody\" and \"access\"; Quebec's Civil Code still uses \"garde\". See item 12 above (the one-year rule) and chapter 29, item 9 (divorce and keeping coverage).", "urls": ["https://laws-lois.justice.gc.ca/eng/acts/d-3.4/fulltext.html", "https://laws-lois.justice.gc.ca/eng/regulations/SOR-97-175/FullText.html", "https://www.justice.gouv.qc.ca/fileadmin/user_upload/contenu/professionnels-securise/EN/parenting/2_Parenting.pdf"]}, {"id": "10-014", "chapter_num": 10, "chapter_title": "Dating and Marriage", "chapter_file": "10-dating-and-marriage.md", "number": 14, "title": "Read the marriage trend before listening to your elders", "money": "0", "time": "low", "willpower": "no", "benefit": "mid", "dimension": "time", "evidence": "B", "grade": "B", "disputed": false, "cost": "Nothing; five minutes of perspective.", "plain": "Marriage in Canada has been getting rarer for decades, with a sharp dip in the pandemic year. There is no normal timeline you are behind on, and anyone quoting a divorce rate should say what the denominator is.", "benefit_text": "Statistics Canada's series shows the crude marriage rate falling from 8.1 per 1,000 people in 1921 to 3.9 in 2019, with 2.6 in 2020; crude rates divide by the whole population, not by married couples.", "sources": "Statistics Canada marriage chart — https://www150.statcan.gc.ca/n1/daily-quotidien/221114/cg-b002-eng.htm", "notes": "", "urls": ["https://www150.statcan.gc.ca/n1/daily-quotidien/221114/cg-b002-eng.htm"]}, {"id": "10-015", "chapter_num": 10, "chapter_title": "Dating and Marriage", "chapter_file": "10-dating-and-marriage.md", "number": 15, "title": "Negotiate the unpaid-work split before the wedding", "money": "0", "time": "low", "willpower": "some", "benefit": "mid", "dimension": "time", "evidence": "B", "grade": "B", "disputed": false, "cost": "One uncomfortable conversation; no money.", "plain": "In Canadian households women still do noticeably more unpaid housework and adult caregiving than men, and the chores split along traditional lines. Talk about the division of housework early, with specifics and hours, instead of discovering the gap years in.", "benefit_text": "Time-use data shows women average about forty-two minutes more per day on adult caregiving than men; naming the gap early prevents the most common long-term resentment.", "sources": "Statistics Canada time-use Daily — https://www150.statcan.gc.ca/n1/daily-quotidien/180730/dq180730a-eng.htm", "notes": "", "urls": ["https://www150.statcan.gc.ca/n1/daily-quotidien/180730/dq180730a-eng.htm"]}, {"id": "10-016", "chapter_num": 10, "chapter_title": "Dating and Marriage", "chapter_file": "10-dating-and-marriage.md", "number": 16, "title": "Build closeness with structured questions, not pickup lines", "money": "0", "time": "mid", "willpower": "some", "benefit": "mid", "dimension": "time", "evidence": "B", "grade": "B", "disputed": false, "cost": "An evening and some vulnerability; no money.", "plain": "Taking turns answering a set of questions that get gradually more personal builds closeness faster than small talk, faster than rehearsed charm. The mechanism is mutual self-disclosure, not any special list.", "benefit_text": "The classic closeness-generating procedure produced measurable increases in interpersonal closeness in the lab; the active ingredient is reciprocal, escalating disclosure.", "sources": "Aron A, et al. (1997), Personality and Social Psychology Bulletin — https://doi.org/10.1177/0146167297234003", "notes": "", "urls": ["https://doi.org/10.1177/0146167297234003"]}, {"id": "10-017", "chapter_num": 10, "chapter_title": "Dating and Marriage", "chapter_file": "10-dating-and-marriage.md", "number": 17, "title": "Treat long distance as normal; plan the move-in", "money": "0", "time": "mid", "willpower": "some", "benefit": "mid", "dimension": "time", "evidence": "B", "grade": "B", "disputed": false, "cost": "Travel money and communication effort.", "plain": "Long-distance couples do about as well as close ones while apart; the risky moment is moving in together, when idealized images collide with daily habits. Plan the first months of cohabitation deliberately instead of assuming closeness will carry over.", "benefit_text": "Studies find long-distance dating relationships are comparably stable and satisfying; reunions that become cohabitation are the transition that needs active management.", "sources": "Stafford L, Merolla AJ, Castle JD (2006) — https://doi.org/10.1177/0265407506070472 ; Stafford L, Merolla AJ (2007) — https://doi.org/10.1177/0265407507072578 ; Dargie E, et al. (2015) — https://doi.org/10.1080/0092623X.2013.864367", "notes": "", "urls": ["https://doi.org/10.1080/0092623X.2013.864367", "https://doi.org/10.1177/0265407506070472", "https://doi.org/10.1177/0265407507072578"]}, {"id": "10-018", "chapter_num": 10, "chapter_title": "Dating and Marriage", "chapter_file": "10-dating-and-marriage.md", "number": 18, "title": "Fight about the issue, never about the person", "money": "0", "time": "low", "willpower": "yes", "benefit": "mid", "dimension": "time", "evidence": "B", "grade": "B", "disputed": false, "cost": "Self-control in the moment; no money.", "plain": "Hostile conflict — contempt, mockery, name-calling — is what damages health and relationships, not disagreement itself. Argue about the dishes, the money, the plan; leave the other person's character out of it.", "benefit_text": "Hostile marital interactions are linked with slower wound healing and higher inflammatory markers; contempt is the conflict style most tied to bad outcomes.", "sources": "Robles TF, et al. (2014) — https://doi.org/10.1037/a0031859 ; Kiecolt-Glaser JK, et al. (2005), Archives of General Psychiatry — https://doi.org/10.1001/archpsyc.62.12.1377", "notes": "", "urls": ["https://doi.org/10.1001/archpsyc.62.12.1377", "https://doi.org/10.1037/a0031859"]}, {"id": "10-019", "chapter_num": 10, "chapter_title": "Dating and Marriage", "chapter_file": "10-dating-and-marriage.md", "number": 19, "title": "Keep a separate ledger for marrying to please your family", "money": "0", "time": "low", "willpower": "some", "benefit": "low", "dimension": "money", "evidence": "C", "grade": "C", "disputed": false, "cost": "A notebook and honesty; no money.", "plain": "If part of your reason to marry is parental pressure, write down what that pressure is costing you — money spent, choices narrowed, resentment banked — in a separate account from your own reasons. Mixed books produce confused decisions.", "benefit_text": "Separating the family-pressure account from your own account makes the real price of compliance visible and keeps it from silently subsidizing a marriage you would not otherwise choose.", "sources": "Statistics Canada marriage chart — https://www150.statcan.gc.ca/n1/daily-quotidien/221114/cg-b002-eng.htm", "notes": "", "urls": ["https://www150.statcan.gc.ca/n1/daily-quotidien/221114/cg-b002-eng.htm"]}, {"id": "11-001", "chapter_num": 11, "chapter_title": "Red Lines for Tech Workers", "chapter_file": "11-red-lines-for-tech-workers.md", "number": 1, "title": "Ask three questions before you run it; unauthorized computer use is a crime", "money": "0", "time": "low", "willpower": "some", "benefit": "high", "dimension": "freedom", "evidence": "B", "grade": "B", "disputed": false, "cost": "Five minutes of honest thought; no money.", "plain": "Before you run a script, before you test a system, before you use someone else's credentials, ask: whose interests does this harm, how able are they to come after me, and what traces am I leaving. Curiosity and good intentions are not defences. If you are investigated, say nothing and call a criminal lawyer first.", "benefit_text": "Unauthorized use of a computer — obtaining services, intercepting functions, or trafficking passwords, all without permission and dishonestly — carries up to ten years in prison. The three questions keep you on the safe side of that line.", "sources": "Criminal Code s.342.1 — https://lois.justice.gc.ca/eng/acts/C-46/page-55.html", "notes": "", "urls": ["https://lois.justice.gc.ca/eng/acts/C-46/page-55.html"]}, {"id": "11-002", "chapter_num": 11, "chapter_title": "Red Lines for Tech Workers", "chapter_file": "11-red-lines-for-tech-workers.md", "number": 2, "title": "Leave the data alone on your way out", "money": "0", "time": "low", "willpower": "yes", "benefit": "high", "dimension": "freedom", "evidence": "B", "grade": "B", "disputed": false, "cost": "Restraint when you are angry; no money.", "plain": "When you quit, when you are fired, hand back every account and permission and touch nothing. Deleting databases, encrypting files, planting backdoors, locking systems over a pay dispute is mischief against computer data, even if the company owes you money. Collect debts through employment standards, through a lawyer — not through the server room.", "benefit_text": "Wilfully destroying or altering computer data, or blocking someone entitled from accessing it, is mischief under the Criminal Code; being owed wages is no defence.", "sources": "Criminal Code s.430(1.1) — https://laws-lois.justice.gc.ca/eng/acts/c-46/section-430.html", "notes": "", "urls": ["https://laws-lois.justice.gc.ca/eng/acts/c-46/section-430.html"]}, {"id": "11-003", "chapter_num": 11, "chapter_title": "Red Lines for Tech Workers", "chapter_file": "11-red-lines-for-tech-workers.md", "number": 3, "title": "Scrape only public pages and keep personal information out", "money": "0", "time": "low", "willpower": "some", "benefit": "high", "dimension": "freedom", "evidence": "B", "grade": "B", "disputed": false, "cost": "The discipline to stay within public pages; no money.", "plain": "Crawling pages anyone can see is one thing; bypassing logins, defeating anti-scraping controls, harvesting names, emails, and phone numbers is another. Bypassing access controls can be unauthorized computer use, and collecting personal information without consent breaches federal privacy law. Never sell scraped data.", "benefit_text": "Stays clear of the unauthorized-use offence and of PIPEDA's consent and appropriate-purposes rules; scraped personal data sold onward multiplies every risk.", "sources": "Criminal Code s.342.1 — https://lois.justice.gc.ca/eng/acts/C-46/page-55.html ; PIPEDA — https://lois.justice.gc.ca/eng/acts/P-8.6/FullText.html", "notes": "", "urls": ["https://lois.justice.gc.ca/eng/acts/C-46/page-55.html", "https://lois.justice.gc.ca/eng/acts/P-8.6/FullText.html"]}]);
